SELECT gsof.*,
(SELECT gps.PERIOD_SET_NAME FROM GLD_PERIOD_SET gps WHERE gps.PERIOD_SET_ID = gsof.PERIOD_SET_ID) AS periodSetName,
(SELECT gas.ACCOUNT_SET_NAME FROM gld_account_set gas WHERE gas.ACCOUNT_SET_ID = gsof.ACCOUNT_SET_ID) AS accountSetName,
(
SELECT
fc.currency_name
FROM
fnd_currency fc
WHERE
fc.currency_code = gsof.functional_currency
) functional_currency_cn
FROM
gld_set_of_books gsof


